//! Session staging must retain public Engine::advance validation and rollback.
use moloch_replay::{engine::Engine,session::{Session,BatchEntry}};
use serde_json::{json,Value};
use std::{fs,path::{Path,PathBuf},sync::atomic::{AtomicU64,Ordering}};
struct Temp(PathBuf);impl Temp{fn new()->Self{static N:AtomicU64=AtomicU64::new(0);let p=std::env::temp_dir().join(format!("session-staging-{}-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos(),N.fetch_add(1,Ordering::Relaxed)));fs::create_dir(&p).unwrap();Self(p)}}impl Drop for Temp{fn drop(&mut self){let _=fs::remove_dir_all(&self.0);}}
fn policy()->Value{json!({"quantity":2})}
fn seed()->Value{json!({"runId":"staging-fixture","availableCash":"1000.000000","accountSnapshotHash":"a".repeat(64),"observedAt":"2026-10-13T00:00:00Z"})}
fn state(e:&Engine)->Value{json!({"report":e.report().unwrap(),"orders":e.order_records(),"fills":e.fills(),"books":e.live_package_books(),"bindings":e.live_order_bindings(),"required":e.required_exchanges(),"packages":e.package_records()})}
fn files(p:&Path)->Vec<Vec<u8>>{["events.jsonl","head.json","report.json"].iter().map(|n|fs::read(p.join(n)).unwrap()).collect()}
fn inputs(events:&[Value])->Vec<BatchEntry<'_>>{events.iter().enumerate().map(|(i,event)|BatchEntry{source_id:"original",sequence:i as u64+1,event}).collect()}
fn events()->Vec<Value>{let corpus:Value=serde_json::from_str(include_str!("reference/golden.json")).unwrap();let book=corpus[0]["steps"][0]["event"].clone();let mut e=Engine::new_live(&policy()).unwrap();e.advance(&book).unwrap();let q=e.order_records().into_iter().find(|q|q["side"]=="YES").unwrap();let base=|kind:&str,at:&str|json!({"type":kind,"source":"official_sig_api_v1","receiptHash":"b".repeat(64),"orderId":q["id"],"actualOrderId":"201","exchangeId":q["exchangeId"],"marketId":q["marketId"],"side":q["side"],"action":"buy","quantity":q["quantity"],"price":q["price"],"receivedAt":at});let ack=base("actual_order_ack","2026-10-13T00:00:01Z");let mut fill=base("actual_fill","2026-10-13T00:00:05Z");fill["fillId"]=json!("301");fill["quantity"]=json!(1);fill["fee"]=json!("0.000000");fill["executedAt"]=json!("2026-10-13T00:00:04Z");let mut terminal=base("actual_order_terminal","2026-10-13T00:00:06Z");terminal["status"]=json!("canceled");terminal["filledQuantity"]=json!(1);terminal["fillsComplete"]=json!(true);vec![book,ack,fill,terminal]}
#[test]fn serial_staging_matches_transactional_engine_every_actual_financial_prefix(){let t=Temp::new();let mut s=Session::open_live(&t.0.join("bank"),&policy(),&seed()).unwrap();let mut reference=Engine::new_live(&policy()).unwrap();for(i,event)in events().iter().enumerate(){reference.advance(event).unwrap();s.accept("original",i as u64+1,event).unwrap();assert_eq!(state(s.engine()),state(&reference));}assert_eq!(s.engine().fills().len(),1);assert_eq!(s.engine().report().unwrap()["ownedCost"],"0.450000");}
#[test]fn batch_consuming_candidate_rolls_back_earlier_ack_and_cash_fill_when_final_terminal_invalid(){let t=Temp::new();let root=t.0.join("bank");let mut s=Session::open_live(&root,&policy(),&seed()).unwrap();let initial=state(s.engine());let original=files(&root);let valid=events();let mut invalid=valid.clone();invalid[3]["filledQuantity"]=json!(2);assert!(s.accept_batch(&inputs(&invalid)).is_err());assert_eq!(files(&root),original);assert_eq!(state(s.engine()),initial);assert_eq!(s.last_source_sequence("original"),0);let outcome=s.accept_batch(&inputs(&valid)).unwrap();assert_eq!(outcome.accepted,vec![true;4]);assert_eq!(s.engine().fills().len(),1);let mut reference=Engine::new_live(&policy()).unwrap();for e in &valid{reference.advance(e).unwrap();}assert_eq!(state(s.engine()),state(&reference));let before=files(&root);assert_eq!(s.accept_batch(&inputs(&valid)).unwrap().accepted,vec![false;4]);assert_eq!(files(&root),before);}
#[test]fn failed_individual_candidate_preserves_all_published_state_and_same_sequence_remains_usable(){let t=Temp::new();let root=t.0.join("bank");let mut s=Session::open_live(&root,&policy(),&seed()).unwrap();let events=events();s.accept("original",1,&events[0]).unwrap();s.accept("original",2,&events[1]).unwrap();let original=files(&root);let before=state(s.engine());let mut bad=events[2].clone();bad["quantity"]=json!(999);assert!(s.accept("original",3,&bad).is_err());assert_eq!(state(s.engine()),before);assert_eq!(files(&root),original);assert_eq!(s.last_source_sequence("original"),2);s.accept("original",3,&events[2]).unwrap();assert_eq!(s.engine().fills().len(),1);}
#[test]fn serial_and_batch_original_bytes_restart_and_poison_recovery_preserve_actual_financial_prefix(){for batch in [false,true]{let t=Temp::new();let root=t.0.join("bank");let mut s=Session::open_live(&root,&policy(),&seed()).unwrap();let events=events();let mut expected=Engine::new_live(&policy()).unwrap();for e in &events{expected.advance(e).unwrap();}if batch{s.accept_batch(&inputs(&events)).unwrap();}else{for(i,e)in events.iter().enumerate(){s.accept("original",i as u64+1,e).unwrap();}}let actual=state(s.engine());assert_eq!(actual,state(&expected));let before=files(&root);drop(s);let s=Session::open_live(&root,&policy(),&seed()).unwrap();assert_eq!(state(s.engine()),actual);assert_eq!(files(&root),before);drop(s);
 let broken=t.0.join("broken");let mut s=Session::open_live(&broken,&policy(),&seed()).unwrap();fs::rename(broken.join("head.json"),broken.join("saved-head")).unwrap();fs::create_dir(broken.join("head.json")).unwrap();if batch{assert!(s.accept_batch(&inputs(&events)).is_err());}else{assert!(s.accept("original",1,&events[0]).is_err());}assert!(s.accept_batch(&[]).unwrap_err().to_string().contains("POISONED"));drop(s);fs::remove_dir(broken.join("head.json")).unwrap();fs::rename(broken.join("saved-head"),broken.join("head.json")).unwrap();let restored=Session::open_live(&broken,&policy(),&seed()).unwrap();let mut prefix=Engine::new_live(&policy()).unwrap();for e in events.iter().take(if batch{4}else{1}){prefix.advance(e).unwrap();}assert_eq!(state(restored.engine()),state(&prefix));}}
#[test]fn single_and_batch_commit_identical_original_bytes_for_actual_accounting(){let t=Temp::new();let a=t.0.join("serial");let b=t.0.join("batch");let mut serial=Session::open_live(&a,&policy(),&seed()).unwrap();let mut batch=Session::open_live(&b,&policy(),&seed()).unwrap();let events=events();for(i,e)in events.iter().enumerate(){serial.accept("original",i as u64+1,e).unwrap();}batch.accept_batch(&inputs(&events)).unwrap();assert_eq!(files(&a),files(&b));assert_eq!(state(serial.engine()),state(batch.engine()));}
